import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DWfJTVRq.js";const u=JSON.parse(`{"title":"Introduction","description":"DaruDB is an embedded database that keeps an application's data in one local file, with one engine written in Rust that programs in Rust, Node.js and Dart all…","frontmatter":{"title":"Introduction","order":1,"prev":false,"next":{"text":"Getting started","link":"/guide/getting-started"}},"headers":[{"level":2,"title":"Packages","slug":"packages","link":"#packages","children":[]},{"level":2,"title":"What it is designed for","slug":"what-it-is-designed-for","link":"#what-it-is-designed-for","children":[]},{"level":2,"title":"How it is built","slug":"how-it-is-built","link":"#how-it-is-built","children":[]},{"level":2,"title":"Where it stands","slug":"where-it-stands","link":"#where-it-stands","children":[]}],"relativePath":"guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":1791015517000}`),s={name:"guide/introduction.md"};function r(o,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>DaruDB is an embedded database that keeps an application&#39;s data in one local file, with one engine written in Rust that programs in Rust, Node.js and Dart all use.</p><p>An embedded database runs inside your program rather than beside it. There is no server to install, start or connect to: your program opens a file, reads and writes objects in it, and closes it. That makes it the kind of database a desktop application, a mobile app, a command-line tool or a small server keeps its own data in.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Language</th><th>What it is</th></tr></thead><tbody><tr><td>Crate <code>darudb</code></td><td>Rust</td><td>The engine itself, and a library a Rust program uses directly</td></tr><tr><td>npm package <code>darudb</code></td><td>Node.js</td><td>A binding over the engine, with a typed TypeScript API, synchronous and asynchronous</td></tr><tr><td>Dart package <code>darudb</code></td><td>Dart</td><td>A binding over the engine for Flutter apps and Dart programs, synchronous and with <code>Future</code>s, whose generator <code>darudb_generator</code> stores annotated classes</td></tr></tbody></table><p>The Rust crate is not only the core the other packages are built on. A Rust program depends on it the way a Node.js program depends on the npm package, and gets the same collections, queries, migrations and tools. It also has two things the bindings do not: the <a href="./../engine/storage-kernel">storage kernel</a> of named byte trees under the objects, and the <a href="./../engine/bindings">calls bindings are built on</a>.</p><p>Choose your language with the switch at the top of the sidebar. The examples on every page, and the API and Types sections, follow it, and the site remembers the choice.</p><h2 id="what-it-is-designed-for" tabindex="-1">What it is designed for <a class="header-anchor" href="#what-it-is-designed-for" aria-label="Permalink to &quot;What it is designed for&quot;">​</a></h2><p>Five requirements shape every decision, in this order of priority.</p><ol><li><strong>Performance.</strong> Reads and writes faster than the embedded SQL engines applications usually reach for, measured at the same durability settings.</li><li><strong>Encryption.</strong> The whole file encrypted and authenticated, with keys derived and stored properly.</li><li><strong>Stability.</strong> A file that survives a crash or a power cut, damage that is detected and can be repaired, and several processes using one file at the same time.</li><li><strong>Compatibility.</strong> Old and new releases of Windows, macOS, Linux, iOS and Android. The file format carries its version, and every new format version and every new version of your schema comes with a migration from the one before.</li><li><strong>Ease of use.</strong> A schema that is easy to declare and queries that are easy to write, with results that are plain objects rather than handles tied to the open database.</li></ol><p>These are goals. Each one becomes a claim when the benchmark or the test suite that proves it is in the repository.</p><h2 id="how-it-is-built" tabindex="-1">How it is built <a class="header-anchor" href="#how-it-is-built" aria-label="Permalink to &quot;How it is built&quot;">​</a></h2><p>The engine is written once, in Rust, and the Node.js and Dart packages are thin bindings over it that add no behaviour of their own. Every rule about the file lives in the engine, which is what makes a file written from one language read the same from another, and what gives every error the same <code>code</code> in every language. <a href="./../engine/architecture">How the engine is built</a> goes through its layers.</p><h2 id="where-it-stands" tabindex="-1">Where it stands <a class="header-anchor" href="#where-it-stands" aria-label="Permalink to &quot;Where it stands&quot;">​</a></h2><ul><li><strong>Storage.</strong> A copy-on-write tree of pages, each verified against the check its parent recorded before it is used, so a damaged page is reported rather than read. A commit is durable when it returns; a deferred commit returns before the disk has it and reaches it within a second by default.</li><li><strong>Encryption.</strong> A database created with a key or a password is encrypted and authenticated, every page of it, and changing the password re-encrypts nothing.</li><li><strong>Several processes.</strong> Processes share one file through the operating system&#39;s file locks alone: one writes at a time, readers never wait, and a process that dies leaves nothing behind.</li><li><strong>Objects.</strong> Schemas, collections, indexes, links and embedded objects, queries built in code or written as text, and migrations from one schema version to the next.</li><li><strong>Tools.</strong> An integrity check, online backup, compaction, and salvage of a damaged file.</li><li><strong>Tests.</strong> Thousands of simulated power cuts and hundreds of real processes killed in the middle of a commit, with encryption on and off, and several processes reading and writing one file while random ones are killed.</li><li><strong>Packages.</strong> The Rust crate, the Node.js package and the Dart package have all of the above. Nothing is published yet: each is built from source.</li></ul><p>Still to come: prebuilt binaries for every supported platform, so that no package needs a Rust compiler to install.</p>',16)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
